#= The far route of the point-observer derivative kernels against golden values of the near
route's closed forms (k-series in Double64), and NaN where it refuses. =#
using Test, GilaElectromagnetics, DoubleFloats

# (der, offset in cells) => the a <= b entries of K^g_ab, g outermost, cell (1, 2, 3)/4, f = 1/4
const drvGld = Dict(
    (0, (4, 2, 1)) => ComplexF64[-0.08295830093750657 + 0.07584162507579764im, 0.08000315957512293 + 0.04621105000657116im, 0.057328298214078074 + 0.03430079304029256im, -0.08612622959112298 + 0.07599331370096944im, 0.05580240615605142 + 0.03408785987612185im, -0.12200626520465427 + 0.05656974574481898im],
    (1, (-3, 2, 1)) => ComplexF64[-0.09301130971213295 + 0.0524868568526934im, -0.021410046211511463 + 0.03936477445497228im, -0.013176602385587158 + 0.02920479389623615im, 0.16875126495759396 + 0.13500336496743093im, 0.1276385802265712 + 0.010851765320621378im, 0.0793875979474605 + 0.128881819844997im, -0.12013083568851345 - 0.16959816601323702im, 0.0911874883611332 - 0.023182655865129735im, 0.1276385802265712 + 0.010851765320621378im, 0.02266614913010407 - 0.07818343790020882im, -0.0789282692763459 + 0.022750792569884822im, -0.0999768923955946 - 0.17014427702297275im, -0.08154730186858153 - 0.12509369991068092im, 0.1276385802265712 + 0.010851765320621378im, 0.0018238213509997477 - 0.029304200987563665im, -0.14729896875934026 - 0.13154770123703224im, -0.001256102918592607 + 0.038818663445236545im, 0.09210487166193305 - 0.05195558646612097im],
    (2, (2, -1, 3)) => ComplexF64[0.05750803473148126 + 0.012583681917928745im, 0.011811650510144966 + 0.008469055536585652im, -0.05177325011045573 - 0.03778830071357102im, 0.0620813732536873 - 0.02519057162517357im, 0.013251044225184846 + 0.011833272359953535im, 0.006767195998397628 - 0.07560151143072262im, 0.007929884405871938 - 0.006623681109531849im, -0.0010969287380957911 + 0.018913628943810153im, 0.013251044225184846 + 0.011833272359953535im, 0.0077407215194346506 - 0.006666063086867493im, -0.013370059319956119 - 0.011837387046801174im, -0.023434138133852644 - 0.01689572909583566im, -0.035430160325288215 + 0.029296085949927466im, 0.013251044225184846 + 0.011833272359953535im, -0.05641110599338547 - 0.031497310861738896im, 0.0029730304652113865 + 0.05524699961669731im, -0.019552372029579615 - 0.0018029924497181592im, 0.06514330943041184 + 0.04962568776037219im, 0.06199225229190615 - 0.024465085152059494im, 0.011622487623707678 + 0.008426673559250008im, -0.013370059319956119 - 0.011837387046801174im, 0.057117601262591876 + 0.012478298208425881im, 0.0500217311611034 + 0.03740649133432013im, 0.007068508505505856 - 0.07477064124810569im, -0.0023554939764742246 - 0.05475203103460984im, -0.013370059319956119 - 0.011837387046801174im, -0.019552372029579615 - 0.0018029924497181592im, 0.03441519295944433 - 0.029178812060243253im, -0.056020672524496086 - 0.031391927152236036im, -0.06327277538628825 - 0.04923976369427366im, 0.06848069166509614 + 0.20758988162169037im, -0.019552372029579615 - 0.0018029924497181592im, 0.048800219645244336 - 0.01745869890312629im, 0.06887112513398552 + 0.20769526533119326im, -0.04766623718462918 + 0.01734553970028972im, 0.11243177851788155 + 0.06288923801397493im],
)

@testset "Far derivative kernels" begin
    scl = (1, 2, 3) .// 4 .|> Rational{BigInt}
    for ((der, D), gld) in drvGld
        nG = length(GilaElectromagnetics.drvGam(der))
        Ds = [Rational{BigInt}.(D .* scl), (1 // 4, 0, 0) .|> Rational{BigInt}]
        for T in (Float64, Double64)
            ego = Array{Complex{T}}(undef, 3, 3, nG, 2)
            GilaElectromagnetics.drvFar!(ego, Ds, scl, 0.25, der)
            val = [ComplexF64(ego[a, b, g, 1]) for g in 1:nG for a in 1:3 for b in a:3]
            @test maximum(abs, val .- gld) <= (T == Float64 ? 32 : 2) * eps(maximum(abs, gld))
            @test all(isnan, ego[:, :, :, 2])
        end
    end
end
